mapper.select:

where p.del_flag = '0'

    and p.plot_name like concat('%', #{plotName}, '%')


    and p.plot_code like concat('%', #{plotCode}, '%')


    and p.enterprise_id = #{enterpriseId}


    and p.status = #{status}

order by p.plot_id desc


where p.del_flag = '0' and p.status = '0'

    and p.enterprise_id = #{enterpriseId}

order by p.plot_name asc

mapper.update:
update trace_vineyard_plot
enterprise_id = #{enterpriseId}, plot_name = #{plotName}, plot_code = #{plotCode}, area_ha = #{areaHa}, soil_type = #{soilType}, elevation_m = #{elevationM}, gps_coordinates = #{gpsCoordinates}, planted_variety = #{plantedVariety}, vine_age = #{vineAge}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where plot_id = #{plotId}
